// lookup demo — Black pepper (jahdb demo program)
var DATA={"Black pepper":"Black pepper is the king of spices: dried peppercorns, ground fresh for pungent heat on everything."};
function lookup(q){q=String(q).toLowerCase();var h=[];for(var k in DATA){if((k+" "+DATA[k]).toLowerCase().indexOf(q)>=0)h.push(k+": "+DATA[k]);}return h.length?h.join("\n"):"no match for "+q;}
function listAll(){return Object.keys(DATA).join(", ");}
console.log("sample lookup:");console.log(lookup("pungent heat"));

